USE tvs_manufacturing;

SET FOREIGN_KEY_CHECKS = 0;
TRUNCATE TABLE production;
TRUNCATE TABLE defects;
TRUNCATE TABLE plants;
TRUNCATE TABLE machines;
TRUNCATE TABLE products;
SET FOREIGN_KEY_CHECKS = 1;


-- plants: 3 rows

-- machines: 11 rows

-- products: 6 rows

-- production: 7940 rows

-- defects: 3960 rows

SELECT 'Data inserted. Now run 03_verify_import.sql' AS status;
